IG$.cVis.singleseries = $s.extend(IG$.cVis.cartesian, {
    charttype: "singleseries",
	subtype: null,
    is_single_series: 1,
    _create_chart: function(mresult) {
        var me = this,
            rcs = me.subtype,
            coption = {
                chart: {}
            },
            chart = coption.chart,
            is3d;

        if (rcs == "pie3d")
        {
            rcs = "pie";
            is3d = 1;
        }
        chart.type = is3d ? "pie-3d" : "pie";
        me._apply_option(coption, mresult);
        return coption;
    }
});