IG$.cVis.cartesian = $s.extend(IG$.cVis._anychart, {
    charttype: "cartesian",
	subtype: null,

    _apply_option: function(coption, mresult) {
        var me = this,
            mcr = me.chart_option,
            titleposition = mcr.titleposition || "",
            legendposition = mcr.legendposition = mcr.legendposition || "BOTTOM_CENTER",
            chart = coption.chart,
            title,
            legend;

        if (mcr.showtitle && mcr.title)
        {
            title = chart.title = {};
            title.text = mcr.title;
            // title.fontColor("#F44336");
            title.enabled = true;

            if (titleposition.indexOf("BOTTOM_") > -1)
			{
				title.align = "bottom";
			}
			else if (titleposition.indexOf("_LEFT") > -1)
			{
                title.align = "left";
			}
			else if (titleposition.indexOf("_RIGHT") > -1)
			{
                title.align = "right";
			}
			else
			{
			}
        }

        legend = chart.legend = {};

        if (mcr.showlegend)
        {
            legend.enabled = true;
            
            var orient = "horizontal",
                itemposition = "bottom";

            if (legendposition.indexOf("BOTTOM_") > -1)
			{
                itemposition = "bottom";
			}
			else if (legendposition.indexOf("TOP_") > -1)
			{
                itemposition = "top";
			}
			else
			{
				orient = "vertical";
			}
			
			if (orient == "horizontal")
			{
				if (legendposition.indexOf("_RIGHT") > -1)
				{
					itemposition = "right";
				}
				else if (legendposition.indexOf("_LEFT") > -1)
				{
					itemposition = "left";
				}
			}
			else
			{
				if (legendposition.indexOf("RIGHT_") > -1)
				{
					
				}
				else if (legendposition.indexOf("LEFT_") > -1)
				{
					
				}
			}

            legend.itemsLayout = orient;
            legend.position = itemposition;
        }
        else
        {
            legend.enabled = false;
        }
    },

    _create_chart: function(mresult) {
        var me = this,
            mcr = me.chart_option,
            rcs = me.subtype,
            title,
            is3d,
            coption = {
                chart: {}
            },
            chart = coption.chart;

        if (rcs == "column3d")
        {
            rcs = "column";
            is3d = 1;
        }

        chart.type = is3d ? "cartesian3d" : "cartesian";
        chart.defaultSeriesType = rcs || "column";
        me._apply_option(coption, mresult);
        return coption;
    },

    _flat_data: function(mresult, coption) {
        var me = this,
            i, j,
            mcr = me.chart_option,
            fr = mresult.rowfix,
            fc = mresult.colfix,
            data = mresult._tabledata,
            sep = me.getSep(),
            tr = data.length,
            tc = tr ? data[0].length : 0,
            series = [],
            serie,
            categ,
            r, cval, c;

        for (i=fc; i < tc; i++)
        {
            cval = "";
            for (j=0; j < fr; j++)
            {
                c = data[j][i];
                cval += (j > 0 ? sep : "") + (c.text || c.code);
            }
            serie = {
                name: cval,
                data: []
            };

            series.push(serie);
        }

        for (i=fr; i < tr; i++)
        {
            cval = "";
            for (j=0; j < fc; j++)
            {
                c = data[i][j];
                cval += (j > 0 ? sep : "") + (c.text || c.code);
            }
            categ = cval;
            for (j=fc; j < tc; j++)
            {
                serie = series[j - fc];
                c = data[i][j];
                r = {x: categ};
                r.value = c.code;
                r.label = c.text || c.code;
                serie.data.push(r);
            }
        }

        if (me.is_single_series)
        {
            coption.chart.data = series[0].data;
        }
        else
        {
            coption.chart.series = series;

            var yaxis = coption.chart.yAxes = [{
                labels: {
                    format: function() {
                        var format = mcr.yaxisformat || "#,###";
                        return IG$.NumberFormat(format, this.value);
                    }
                }
            }];
        }
        

        return series;
    },

    draw: function(mresult) {
        var me = this,
            data = mresult._tabledata,
            i, j,
            fr = mresult.rowfix,
            fc = mresult.colfix,
            hidden_columns = {},
            mcr = me.chart_option,
            rcs = me.subtype,
            maxchartresult = mcr.maxchartresult,
			useformatvalue = mcr.useformatvalue,
			measures = me.sheetoption.model.measures,
            sep = me.getSep(),
            chartdata = [],
            chart, ds,
            tr = data.length,
            tc = tr ? data[0].length : 0;

        $(me.container).empty();

        var c, cval,
            r,
            map_x = ["categ"],
            map_y = [],
            coption;

        coption = me._create_chart();

        me._flat_data(mresult, coption);

        // coption.container = me.container;
        chart = anychart.fromJson(coption);
        chart.container(me.container);
        chart.draw();
    }
});